import math

def check_expression(a, b, c):
    # The expression simplifies to:
    # E = sqrt(1001/c) + sqrt(1001/a) + sqrt(1001/b)

    try:
        E = math.sqrt(1001 / c) + math.sqrt(1001 / a) + math.sqrt(1001 / b)
    except ZeroDivisionError:
        return False

    # Check if E is close enough to an integer
    # Use a tolerance for floating point comparison
    return abs(E - round(E)) < 1e-9

solutions = []
for a in range(1, 11):
    for b in range(a, 11):
        for c in range(b, 11):
            if check_expression(a, b, c):
                solutions.append((a, b, c))

print(f"Found {len(solutions)} solutions in the range 1 <= a <= b <= c <= 10.")
if solutions:
    print("Solutions:", solutions)
else:
    print("No solutions found in the range.")
